_probe:
// Oracle probe for lane parser-diag (extends lane parser-core's probe): drives the real `rustc_parse::parser::Parser` (pinned nightly,
// rustc-dev) through a small op script per case and prints one JSON object per case.
//
// usage: probe <cases.txt>   (cases: blocks of `### name [edition=YYYY]`, `ops: op op ..`, then the source until the next `###`)
// ops: tok | bump | look:N | check:T | eat:T | ckw:K | ekw:K | expect:T | expect_kw:K | unexpected
//      | tt | tts | ident | field_name | inner_attrs | attr | item_attrs | utis | clear
//      | semi (maybe_consume_incorrect_semicolon(None)) | snap | restore (create_snapshot_for_diagnostic / restore_snapshot)
#![feature(rustc_private)]
extern crate rustc_ast;
extern crate rustc_driver;
extern crate rustc_errors;
extern crate rustc_parse;
extern crate rustc_session;
extern crate rustc_span;

use std::io::Write;
use std::sync::{Arc, Mutex};

use rustc_errors::annotate_snippet_emitter_writer::AnnotateSnippetEmitter;
use rustc_errors::{AutoStream, DiagCtxt};
use rustc_parse::exp;
use rustc_parse::lexer::StripTokens;
use rustc_parse::parser::attr::InnerAttrPolicy;
use rustc_parse::parser::{AllowConstBlockItems, ForceCollect, Parser};
use rustc_parse::parser::token_type::{ExpKeywordPair, ExpTokenPair};
use rustc_session::parse::ParseSess;
use rustc_span::edition::Edition;
use rustc_span::source_map::{FilePathMapping, RealFileLoader, SourceMapInputs};
use rustc_span::{FileName, SourceFileHashAlgorithm};

struct Shared(Arc<Mutex<Vec<u8>>>);
impl Write for Shared {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.0.lock().unwrap().write(buf)
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

macro_rules! tokmap {
    ($s:expr; $($t:ident),*) => { match $s { $(stringify!($t) => exp!($t),)* _ => panic!("tok {}", $s) } };
}
macro_rules! kwmap {
    ($s:expr; $($t:ident),*) => { match $s { $(stringify!($t) => exp!($t),)* _ => panic!("kw {}", $s) } };
}
fn tok(s: &str) -> ExpTokenPair {
    tokmap!(s; Eq, Lt, Le, EqEq, Gt, AndAnd, OrOr, Bang, Tilde, Plus, Minus, Star, And, Or, At, Dot, DotDot,
        DotDotDot, DotDotEq, Comma, Semi, Colon, PathSep, RArrow, FatArrow, Pound, Question, Eof, OpenParen,
        OpenBrace, OpenBracket, CloseParen, CloseBrace, CloseBracket)
}
fn kw(s: &str) -> ExpKeywordPair {
    kwmap!(s; As, Async, Const, Crate, Else, Enum, Extern, Fn, For, If, Impl, In, Let, Loop, Match, Mod, Move,
        Mut, Pub, Ref, Return, Static, Struct, Super, Trait, Type, Unsafe, Use, Where, While, Yield, Pin, Raw,
        AttSyntax, Options)
}

fn esc(s: &str) -> String {
    serde_like(s)
}
fn serde_like(s: &str) -> String {
    let mut o = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

fn run_ops<'a>(p: &mut Parser<'a>, ops: &[&str], ev: &mut Vec<String>) {
    let mut snap = None;
    for op in ops {
        let (name, arg) = op.split_once(':').unwrap_or((op, ""));
        let r: String = match name {
            "tok" => format!("{:?} pos={}", p.token, p.approx_token_stream_pos()),
            "prev" => format!("{:?}", p.prev_token),
            "bump" => {
                p.bump();
                continue;
            }
            "look" => p.look_ahead(arg.parse().unwrap(), |t| format!("{t:?}")),
            "check" => format!("{}", p.check(tok(arg))),
            "eat" => format!("{}", p.eat(tok(arg))),
            "is_kw" => format!("{}", p.token.is_keyword(kw(arg).kw)),
            "ekw" => format!("{}", p.eat_keyword(kw(arg))),
            "expect" => match p.expect(tok(arg)) {
                Ok(r) => format!("Ok({r:?})"),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "expect_kw" => match p.expect_keyword(kw(arg)) {
                Ok(()) => "Ok".to_string(),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "unexpected" => match p.unexpected() {
                Ok(()) => "Ok".to_string(),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "tt" => format!("{:?}", p.parse_token_tree()),
            "tts" => format!("{:?}", p.parse_tokens()),
            "ident" => match p.parse_ident() {
                Ok(i) => format!("Ok({i:?})"),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "field_name" => match p.parse_field_name() {
                Ok(i) => format!("Ok({i:?})"),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "inner_attrs" => match p.parse_inner_attributes() {
                Ok(a) => format!("Ok({a:#?})"),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "attr" => match p.parse_attribute(InnerAttrPolicy::Permitted) {
                Ok(a) => format!("Ok({a:#?})"),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "item_attrs" => match p.parse_item(ForceCollect::No, AllowConstBlockItems::Yes) {
                Ok(Some(i)) => format!("Ok({:#?})", i.attrs),
                Ok(None) => "None".to_string(),
                Err(e) => {
                    e.emit();
                    "Err".to_string()
                }
            },
            "utis" => format!("{:?}", p.token_uninterpolated_span()),
            "clear" => {
                p.clear_expected_token_types();
                continue;
            }
            "semi" => format!("{}", p.maybe_consume_incorrect_semicolon(None)),
            "snap" => {
                snap = Some(p.create_snapshot_for_diagnostic());
                continue;
            }
            "restore" => {
                p.restore_snapshot(snap.take().unwrap());
                continue;
            }
            o => panic!("op {o}"),
        };
        ev.push(format!("{op} => {r}"));
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let text = std::fs::read_to_string(&args[1]).unwrap();
    let mut first = true;
    println!("[");
    for block in text.split("### ").skip(1) {
        let (header, rest) = block.split_once('\n').unwrap();
        let mut hw = header.split_whitespace();
        let name = hw.next().unwrap();
        let edition = match hw.next() {
            None => Edition::Edition2024,
            Some("edition=2015") => Edition::Edition2015,
            Some("edition=2018") => Edition::Edition2018,
            Some("edition=2021") => Edition::Edition2021,
            Some(o) => panic!("header {o}"),
        };
        let (ops_line, src) = rest.split_once('\n').unwrap();
        let ops: Vec<&str> = ops_line.strip_prefix("ops:").unwrap().split_whitespace().collect();
        let src = src.strip_suffix('\n').unwrap_or(src).to_string();
        let inputs = SourceMapInputs {
            file_loader: Box::new(RealFileLoader),
            path_mapping: FilePathMapping::empty(),
            hash_kind: SourceFileHashAlgorithm::Md5,
            checksum_hash_kind: None,
        };
        let out = Arc::new(Mutex::new(Vec::new()));
        let mut ev = Vec::new();
        let mut fatal = false;
        rustc_span::create_session_globals_then(edition, &[], Some(inputs), || {
            let sm: Arc<_> = rustc_span::source_map::get_source_map().unwrap();
            let shared: Box<dyn Write + Send> = Box::new(Shared(out.clone()));
            let emitter = AnnotateSnippetEmitter::new(AutoStream::never(shared))
                .sm(Some(Arc::clone(&sm)))
                .ui_testing(true);
            let dcx = DiagCtxt::new(Box::new(emitter));
            let psess = ParseSess::with_dcx(dcx, Arc::clone(&sm));
            let fname = FileName::Real(sm.path_mapping().to_real_filename(sm.working_dir(), std::path::Path::new("t.rs")));
            let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut p = rustc_parse::unwrap_or_emit_fatal(rustc_parse::new_parser_from_source_str(
                    &psess,
                    fname,
                    src.clone(),
                    StripTokens::Nothing,
                ));
                run_ops(&mut p, &ops, &mut ev);
            }));
            fatal = res.is_err();
            psess.dcx().reset_err_count();
        });
        let stderr = String::from_utf8(out.lock().unwrap().clone()).unwrap();
        if !first {
            println!(",");
        }
        first = false;
        let evs: Vec<String> = ev.iter().map(|e| esc(e)).collect();
        print!(
            "{{\"name\":{},\"edition\":{},\"ops\":{},\"src\":{},\"events\":[{}],\"fatal\":{},\"stderr\":{}}}",
            esc(name.trim()),
            esc(&format!("{edition}")),
            esc(ops_line.strip_prefix("ops:").unwrap().trim()),
            esc(&src),
            evs.join(","),
            fatal,
            esc(&stderr)
        );
    }
    println!("\n]");
}
